$dir=Join-Path $env:LOCALAPPDATA 'MeetingRoomAutoBooking\logs'; $found=$false; foreach($f in (Get-ChildItem -LiteralPath $dir -Filter '*格子结构*.json' | Sort-Object LastWriteTime -Descending)){ $j=Get-Content -LiteralPath $f.FullName -Raw -Encoding UTF8 | ConvertFrom-Json; if($j.target.date -eq '2026-10-21' -and $j.startCol -eq 21){ [ordered]@{file=$f.Name;room=$j.roomName;row=$j.row;target=$j.target;stage=$j.stage;confirm=($j.confirmCandidates | Select-Object -First 1 cls,disabled,rect);selected=($j.selectedCandidates | Select-Object -First 8 cls,rect);cells=($j.matchedCells | ForEach-Object {@{column=$_.column;nodes=($_.nodes | Select-Object -First 2 cls,rect,background)}});rows=($j.candidates | Where-Object children -eq 48 | Select-Object -First 4 cls,children,rect,preview);times=($j.timeLabels | Select-Object -First 3 time,rect)} | ConvertTo-Json -Depth 10 -Compress; $found=$true; break; } }; if(-not $found){'没找到10月21日10点对应的格子结构文件'}
